# Simple GridWorld DP – Value Iteration (Python 3.12+)
import numpy as np

gamma = 0.9
states = [(i, j) for i in range(3) for j in range(3)]
actions = ['U','D','L','R']
# deterministic transitions, -1 reward per step, 0 at goal (2,2)
V = {s: 0.0 for s in states}

def step(s, a):
    i, j = s
    if a == 'U': i = max(i-1, 0)
    if a == 'D': i = min(i+1, 2)
    if a == 'L': j = max(j-1, 0)
    if a == 'R': j = min(j+1, 2)
    return (i, j)

def reward(s, a, ns):
    return 0 if ns == (2,2) else -1

theta = 1e-4
while True:
    delta = 0
    for s in states:
        if s == (2,2):
            continue
        v = V[s]
        V[s] = max(sum(gamma*V[step(s,a)] + reward(s,a,step(s,a)) for a in actions))
        delta = max(delta, abs(v-V[s]))
    if delta < theta:
        break
print('Optimal state values:')
for i in range(3):
    print([round(V[(i,j)],2) for j in range(3)])

