def value_iteration(P,R,gamma,theta=1e-5):
    V = np.zeros(len(P))
    while True:
        delta=0
        for s in range(len(P)):
            v=V[s]
            V[s]=max(sum(P[s][a][s_next]*(R[s][a][s_next]+gamma*V[s_next]) for s_next in range(len(P))) for a in range(len(P[s])))
            delta=max(delta,abs(v-V[s]))
        if delta<theta:
            break
    policy=np.argmax([[sum(P[s][a][s_next]*(R[s][a][s_next]+gamma*V[s_next]) for s_next in range(len(P))) for a in range(len(P[s]))] for s in range(len(P))],axis=1)
    return V,policy

def mc_prediction(episodes, gamma=1.0):
    returns = {}
    N = {}
    V = {}
    for ep in episodes:
        G=0
        for s,r in reversed(ep):
            G = r + gamma*G
            if s not in returns:
                returns[s]=0; N[s]=0
            returns[s]+=G; N[s]+=1; V[s]=returns[s]/N[s]
    return V

